1	//! Rust port of `tests/test11.cpp`: run all eleven `idna` entry points over
2	//! every input and print the results on one space-separated line each.
3	//!
4	//! Inputs come from the command line; with no arguments the C++ driver falls
5	//! back to a fixed trio, and so does this one.
6	
7	#[path = "src/idna/mod.rs"]
8	mod idna;
9	
10	use std::env;
11	use std::ffi::OsString;
12	use std::io::{self, Write};
13	
14	fn main() {
15	    let mut inputs: Vec<Vec<u8>> = Vec::new();
16	
17	    // `argc > 1` in the original: every argument after the program name.
18	    for arg in env::args_os().skip(1) {
19	        inputs.push(arg_bytes(arg));
20	    }
21	
22	    if inputs.is_empty() {
23	        inputs = vec![
24	            b"one".to_vec(),
25	            b"two.three".to_vec(),
26	            b"four.five.six".to_vec(),
27	        ];
28	    }
29	
30	    let stdout = io::stdout();
31	    let mut out = io::BufWriter::new(stdout.lock());
32	
33	    // 调用11个不同的API
34	    for input in &inputs {
35	        let mut line: Vec<u8> = Vec::new();
36	        push_field(&mut line, &idna::to_ascii(input));
37	        push_field(&mut line, &idna::to_unicode(input));
38	        push_field(&mut line, &idna::punycode_encode(input));
39	        push_field(&mut line, &idna::punycode_decode(input));
40	        push_field(&mut line, bool_field(idna::is_valid_domain(input)));
41	        push_field(&mut line, bool_field(idna::is_valid_label(input)));
42	        push_field(&mut line, bool_field(idna::is_ascii_domain(input)));
43	        push_field(&mut line, bool_field(idna::is_idn_domain(input)));
44	        push_field(&mut line, &idna::to_lower(input));
45	        push_field(&mut line, &idna::normalize(input));
46	        line.extend_from_slice(idna::count_labels(input).to_string().as_bytes());
47	        line.push(b'\n');
48	
49	        if out.write_all(&line).is_err() {
50	            return;
51	        }
52	    }
53	
54	    let _ = out.flush();
55	}
56	
57	/// Appends one value plus the trailing space that `<< value << " "` emits.
58	fn push_field(line: &mut Vec<u8>, value: &[u8]) {
59	    line.extend_from_slice(value);
60	    line.push(b' ');
61	}
62	
63	/// `std::cout << bool` prints `1`/`0` unless `boolalpha` is set, and it isn't.
64	fn bool_field(value: bool) -> &'static [u8] {
65	    if value {
66	        b"1"
67	    } else {
68	        b"0"
69	    }
70	}
71	
72	/// Arguments reach `main` as raw bytes in C++, so take them as raw bytes here
73	/// too rather than requiring valid UTF-8.
74	#[cfg(unix)]
75	fn arg_bytes(arg: OsString) -> Vec<u8> {
76	    use std::os::unix::ffi::OsStringExt;
77	    arg.into_vec()
78	}
79	
80	#[cfg(not(unix))]
81	fn arg_bytes(arg: OsString) -> Vec<u8> {
82	    arg.to_string_lossy().into_owned().into_bytes()
83	}
84

1	//! Byte-faithful re-implementation of the `idna` C++ helper library.
2	//!
3	//! The C++ library threads everything through `std::string`, which is a plain
4	//! byte container. Nothing in it decodes UTF-8, so a faithful port has to work
5	//! on bytes too: `length()` counts bytes, `substr` slices at byte offsets, and
6	//! `::tolower` in the "C" locale only touches `A`..=`Z`. Working on `&[u8]`
7	//! rather than `&str` keeps that behaviour exact and also lets the driver
8	//! handle arguments that are not valid UTF-8.
9	
10	// The library mirrors the C++ surface; the test11 driver only exercises part of it.
11	#![allow(dead_code)]
12	
13	pub mod convert;
14	pub mod labels;
15	pub mod transform;
16	pub mod validate;
17	
18	pub use convert::{punycode_decode, punycode_encode, to_ascii, to_unicode};
19	pub use labels::count_labels;
20	pub use transform::{normalize, to_lower};
21	pub use validate::{is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};
22	
23	/// ASCII Compatible Encoding prefix that marks a punycode-encoded label.
24	pub const ACE_PREFIX: &[u8] = b"xn--";
25	
26	/// Longest label the validator accepts, in bytes.
27	pub const MAX_LABEL_LENGTH: usize = 63;
28	
29	/// Shortest label the validator accepts, in bytes.
30	pub const MIN_LABEL_LENGTH: usize = 1;
31	
32	/// Longest domain the validator accepts, in bytes.
33	pub const MAX_DOMAIN_LENGTH: usize = 255;
34	
35	/// Separator between labels.
36	pub const LABEL_SEPARATOR: u8 = b'.';
37	
38	/// Mirrors `idna::get_max_label_length()`.
39	pub fn get_max_label_length() -> i32 {
40	    MAX_LABEL_LENGTH as i32
41	}
42	
43	/// Mirrors `idna::get_min_label_length()`.
44	pub fn get_min_label_length() -> i32 {
45	    MIN_LABEL_LENGTH as i32
46	}
47

1	//! Conversion between the Unicode and ASCII Compatible Encoding forms.
2	
3	use super::transform::to_lower;
4	use super::ACE_PREFIX;
5	
6	/// Mirrors `idna::to_ascii()`: `"xn--" + to_lower(s)`.
7	///
8	/// The prefix is added unconditionally — the C++ routine never checks whether
9	/// the input is already ASCII or already prefixed, so `to_ascii("xn--a")`
10	/// yields `"xn--xn--a"`.
11	pub fn to_ascii(input: &[u8]) -> Vec<u8> {
12	    let mut out = Vec::with_capacity(ACE_PREFIX.len() + input.len());
13	    out.extend_from_slice(ACE_PREFIX);
14	    out.extend_from_slice(&to_lower(input));
15	    out
16	}
17	
18	/// Mirrors `idna::punycode_encode()`: `"xn--" + s`.
19	///
20	/// Same as [`to_ascii`] but without the case fold.
21	pub fn punycode_encode(input: &[u8]) -> Vec<u8> {
22	    let mut out = Vec::with_capacity(ACE_PREFIX.len() + input.len());
23	    out.extend_from_slice(ACE_PREFIX);
24	    out.extend_from_slice(input);
25	    out
26	}
27	
28	/// Mirrors `idna::to_unicode()`: `s.find("xn--") == 0 ? s.substr(4) : s`.
29	///
30	/// The comparison is case-sensitive, so an upper-case `"XN--"` is left alone.
31	pub fn to_unicode(input: &[u8]) -> Vec<u8> {
32	    strip_ace_prefix(input).to_vec()
33	}
34	
35	/// Mirrors `idna::punycode_decode()`, which is byte-identical to `to_unicode()`.
36	pub fn punycode_decode(input: &[u8]) -> Vec<u8> {
37	    strip_ace_prefix(input).to_vec()
38	}
39	
40	/// Drops a leading `"xn--"`, leaving anything else untouched.
41	fn strip_ace_prefix(input: &[u8]) -> &[u8] {
42	    match input.strip_prefix(ACE_PREFIX) {
43	        Some(rest) => rest,
44	        None => input,
45	    }
46	}
47

1	//! Label counting.
2	
3	use super::LABEL_SEPARATOR;
4	
5	/// Mirrors `idna::count_labels()`: one more than the number of `.` bytes.
6	///
7	/// Empty labels are counted, so `""` is 1, `"."` is 2 and `"a..b"` is 3. The
8	/// C++ counter is an `int`, which is what the return type reflects.
9	pub fn count_labels(input: &[u8]) -> i32 {
10	    let dots = input.iter().filter(|&&b| b == LABEL_SEPARATOR).count();
11	    dots as i32 + 1
12	}
