#!/usr/bin/perl
# Differential fuzzer, round 1, strategy "argv-shape".
#
# Focus: the CLI contract (argv arity / shape), not the string algorithms.
# Each case is a full argv LIST of raw byte strings. Both binaries are run via
# fork + list-form exec (no shell, so no re-splitting), stdout goes to separate
# files, and the files are compared with `cmp -s`. Exit codes compared too.

use strict;
use warnings;
use POSIX ();

my $CPP     = "/workspace/dataset/test11_executable";
my $RUST    = "/output/test11";
my $SCRATCH = "/tmp/wf-fuzz-r1-7";
my $OUTDIR  = "$SCRATCH/runs";
mkdir $OUTDIR unless -d $OUTDIR;

my $CPP_OUT  = "$OUTDIR/cpp.out";
my $RUST_OUT = "$OUTDIR/rust.out";
my $CPP_ERR  = "$OUTDIR/cpp.err";
my $RUST_ERR = "$OUTDIR/rust.err";

my $count = 0;
my @mismatches;

sub run_bin {
    my ($bin, $argv, $outpath, $errpath) = @_;
    my $pid = fork();
    die "fork failed: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $outpath) or POSIX::_exit(126);
        open(STDERR, '>', $errpath) or POSIX::_exit(126);
        exec { $bin } ($bin, @$argv);
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?;
    if ($st & 127) { return "sig" . ($st & 127); }
    return "exit" . ($st >> 8);
}

sub slurp {
    my ($p) = @_;
    open(my $fh, '<:raw', $p) or return '';
    local $/;
    my $d = <$fh>;
    close $fh;
    return defined($d) ? $d : '';
}

# printf-escaped, shell-safe rendering of one argv element
sub qarg {
    my ($a) = @_;
    if (length($a) && $a !~ /[^\x20-\x7e]/ && $a !~ /['\\]/) {
        return "'" . $a . "'";
    }
    my $esc = join('', map { sprintf('\\x%02x', ord($_)) } split(//, $a));
    return "\"\$(printf '$esc')\"";
}

sub repro_cmd {
    my ($argv) = @_;
    my $joined = join(' ', map { qarg($_) } @$argv);
    return "$CPP $joined > /tmp/c.out; echo \"exit=\$?\"; "
         . "$RUST $joined > /tmp/r.out; echo \"exit=\$?\"; "
         . "cmp /tmp/c.out /tmp/r.out";
}

# a compact repro for cases with huge / very many args
sub repro_cmd_short {
    my ($desc) = @_;
    return $desc;
}

sub check {
    my ($label, $argv, $repro_override) = @_;
    $count++;
    my $crc = run_bin($CPP,  $argv, $CPP_OUT,  $CPP_ERR);
    my $rrc = run_bin($RUST, $argv, $RUST_OUT, $RUST_ERR);
    my $same = (system('cmp', '-s', $CPP_OUT, $RUST_OUT) == 0) ? 1 : 0;
    return if ($same && $crc eq $rrc);

    # must reproduce twice
    my $crc2 = run_bin($CPP,  $argv, "$CPP_OUT.2",  "$CPP_ERR.2");
    my $rrc2 = run_bin($RUST, $argv, "$RUST_OUT.2", "$RUST_ERR.2");
    my $same2 = (system('cmp', '-s', "$CPP_OUT.2", "$RUST_OUT.2") == 0) ? 1 : 0;
    if ($same2 && $crc2 eq $rrc2) {
        print "FLAKY (not reproduced twice): $label\n";
        return;
    }

    my $cb  = slurp($CPP_OUT);
    my $rb  = slurp($RUST_OUT);
    my $ce  = slurp($CPP_ERR);
    my $re  = slurp($RUST_ERR);
    my $tag = sprintf("case%05d", $count);
    open(my $f1, '>:raw', "$OUTDIR/$tag.cpp");  print $f1 $cb;  close $f1;
    open(my $f2, '>:raw', "$OUTDIR/$tag.rust"); print $f2 $rb;  close $f2;
    my $repro = defined($repro_override) ? $repro_override : repro_cmd($argv);

    push @mismatches, { label => $label, tag => $tag, repro => $repro,
                        crc => $crc, rrc => $rrc };
    print "=" x 72, "\n";
    printf("MISMATCH [%s] %s  argc=%d\n", $tag, $label, scalar(@$argv));
    printf("  exit: cpp=%s rust=%s\n", $crc, $rrc);
    printf("  stdout bytes: cpp=%d rust=%d\n", length($cb), length($rb));
    printf("  cpp  : %s\n", vis(substr($cb, 0, 400)));
    printf("  rust : %s\n", vis(substr($rb, 0, 400)));
    printf("  stderr: cpp=%s rust=%s\n", vis(substr($ce,0,200)), vis(substr($re,0,200)))
        if (length($ce) || length($re));
    printf("  files: %s/%s.cpp  %s/%s.rust\n", $OUTDIR, $tag, $OUTDIR, $tag);
    printf("  repro: %s\n", $repro);
}

sub vis {
    my ($s) = @_;
    my $o = '';
    for my $c (split //, $s) {
        my $n = ord($c);
        if ($n >= 0x20 && $n < 0x7f) { $o .= $c }
        elsif ($c eq "\n") { $o .= '\\n' }
        elsif ($c eq "\t") { $o .= '\\t' }
        else { $o .= sprintf('\\x%02x', $n) }
    }
    return $o;
}

# ------------------------------------------------------------- case corpus

# 1. Zero arguments -> built-in default trio. Run repeatedly (determinism).
for my $i (0 .. 4) { check("argc=0 default trio (rep $i)", []); }

my @T = (
    "one", "two.three", "four.five.six",
    "", ".", "..", "...",
    "xn--a", "XN--a", "xn--", "xn--xn--a", "Xn--A",
    "A", "Z", "a", "z", "AbC.DeF",
    "-", "--", "-h", "--help", "-v", "--version", "---",
    "-0", "-.", "--.", "-\xff",
    " ", "  ", "\t", "\n", "\r\n", "a\nb", "a\tb", " one ",
    "'", '"', "''", '""', "\\", "\$", "`", "\$(echo hi)", "\${x}",
    "*", "?", "[a-z]", "~", "!", "#", ";", "|", "&", ">", "<",
    "\xff", "\xfe", "\x80", "\xc3\x28", "\xe0\x80\x80", "\xf0\x9f\x92\xa9",
    "\x01", "\x7f", "\x1b[0m", "\xed\xa0\x80",
    "caf\xc3\xa9", "\xc3\x9f", "I", "i",
    "a" x 63, "a" x 64, "a" x 255, "a" x 256, "a" x 257,
    "." x 63, "a.b.c.d.e.f.g.h.i.j",
    "0", "1", "true", "false",
    "/", "//", "./", "../", "/dev/null", "-o", "-e", "-n", "-E", "--",
);
my $NT = scalar(@T);

# 2. Exactly one argument, for every base token.
for my $t (@T) { check("argc=1 [" . vis(substr($t,0,40)) . "]", [$t]); }

# 3. Exactly two arguments: full pairwise sweep over a prefix + stride sweep.
my @TWO = @T[0 .. 29];
for my $a (@TWO) {
    for my $b (@TWO) {
        check("argc=2 pair", [$a, $b]);
    }
}
for my $i (0 .. $NT - 1) {
    check("argc=2 stride $i", [$T[$i], $T[($i * 7 + 3) % $NT]]);
}

# 4. Exactly three arguments.
for my $i (0 .. $NT - 1) {
    check("argc=3 rot $i",
          [$T[$i], $T[($i * 5 + 1) % $NT], $T[($i * 11 + 7) % $NT]]);
}
my @trio = ("one", "two.three", "four.five.six");
# all 6 permutations of the built-in trio, passed explicitly
for my $p ([0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]) {
    check("argc=3 perm of default trio", [ @trio[@$p] ]);
}

# 5. Empty-string arguments alone and mixed with non-empty.
for my $n (1 .. 14) { check("argc=$n all empty", [ ("") x $n ]); }
check("argc=50 fifty empties", [ ("") x 50 ]);
for my $mask (0 .. 15) {
    my @argv;
    for my $bit (0 .. 3) { push @argv, (($mask >> $bit) & 1) ? "" : "a.b"; }
    check("argc=4 empty-mask $mask", \@argv);
}
for my $mask (0 .. 31) {
    my @argv;
    for my $bit (0 .. 4) { push @argv, (($mask >> $bit) & 1) ? "" : "xn--\xff"; }
    check("argc=5 empty-mask-nonutf8 $mask", \@argv);
}
for my $mask (0 .. 63) {
    my @argv;
    for my $bit (0 .. 5) { push @argv, (($mask >> $bit) & 1) ? "" : "." ; }
    check("argc=6 empty-vs-dot mask $mask", \@argv);
}

# 6. Flag-looking arguments (must be treated as data, never parsed).
my @FLAGS = ("-h", "--help", "-", "--", "-v", "-V", "--version", "-?", "/?",
             "-help", "---help", "-hh", "--HELP", "-h=1", "--help=x",
             "-abc", "--no-op", "--=", "-=", "--a=b", "-e", "-n", "-E",
             "-i", "-o", "-x", "-w", "--", "-\t", "- ");
for my $f (@FLAGS) {
    check("flag alone [" . vis($f) . "]",     [$f]);
    check("flag then data [" . vis($f) . "]", [$f, "one"]);
    check("data then flag [" . vis($f) . "]", ["one", $f]);
    check("flag twice [" . vis($f) . "]",     [$f, $f]);
    check("flag sandwich [" . vis($f) . "]",  ["a", $f, "b.c"]);
    check("flag + empty [" . vis($f) . "]",   [$f, ""]);
    check("empty + flag [" . vis($f) . "]",   ["", $f]);
}
check("argc=" . scalar(@FLAGS) . " all flags at once", [@FLAGS]);
my @inter;
for my $f (@FLAGS) { push @inter, $f, ""; }
check("argc=" . scalar(@inter) . " flags+empties interleaved", \@inter);
check("argc=2 -- then data (getopt terminator)", ["--", "one"]);
check("argc=3 -- -- --", ["--", "--", "--"]);

# 7. Ten arguments.
for my $k (0 .. 39) {
    my @argv = map { $T[($k * 13 + $_ * 3) % $NT] } (0 .. 9);
    check("argc=10 mix $k", \@argv);
}

# 8. Fifty arguments.
for my $k (0 .. 29) {
    my @argv = map { $T[($k * 17 + $_ * 5) % $NT] } (0 .. 49);
    check("argc=50 mix $k", \@argv);
}

# 9. Arity sweep, probing any fixed-size argv assumption.
for my $n (1,2,3,4,5,8,9,10,11,15,16,17,31,32,33,49,50,51,63,64,65,
           100,127,128,129,255,256,257,511,512,1000,2000) {
    check("argc=$n ascending labels", [ map { "l$_" } (0 .. $n - 1) ],
          "argc=$n with args l0..l" . ($n-1));
    check("argc=$n all dots",   [ ('.') x $n ], "argc=$n with every arg '.'");
    check("argc=$n alt empty",  [ map { $_ % 2 ? "" : "a" } (0 .. $n - 1) ],
          "argc=$n alternating '' and 'a'");
    check("argc=$n all non-utf8 \\xff", [ ("\xff") x $n ],
          "argc=$n with every arg the single byte 0xff");
}

# 10. A single 60KB argument (and neighbours), alone and mixed.
my $K60 = 60 * 1024;
for my $size ($K60, $K60 - 1, $K60 + 1, 1024, 4096, 8192, 32768,
              65535, 65536, 65537, 100000) {
    check("argc=1 'a' x $size", [ "a" x $size ],
          "$CPP \"\$(perl -e 'print \"a\" x $size')\" vs $RUST same arg");
}
my @PATS = (["a","a"], [".","dot"], ["\xff","ff"], ["A","upper"],
            ["\xc3\xa9","utf8-2byte"], ["xn--","ace"], ["a.","a-dot"],
            ["\n","newline"], ["\t","tab"], [" ","space"], ["-","dash"]);
for my $p (@PATS) {
    my ($pat, $name) = @$p;
    my $reps = int($K60 / length($pat));
    my $big  = $pat x $reps;
    my $plen = length($big);
    my $pesc = join('', map { sprintf('\\x%02x', ord($_)) } split(//, $pat));
    my $mk   = "\"\$(perl -e 'print \"$pesc\" x $reps')\"";
    check("argc=1 60KB of $name", [$big],
          "$CPP $mk > /tmp/c.out; $RUST $mk > /tmp/r.out; cmp /tmp/c.out /tmp/r.out  # $plen bytes of $name");
    check("argc=2 60KB $name + one", [$big, "one"], "as above plus trailing arg 'one'");
    check("argc=2 one + 60KB $name", ["one", $big], "as above with 'one' first");
    check("argc=3 60KB $name between empties", ["", $big, ""], "60KB $name arg between two empty args");
}
check("argc=1 60KB xn-- prefixed", ["xn--" . ("q" x ($K60 - 4))],
      "single arg: 'xn--' followed by 61436 'q' bytes");
check("argc=1 60KB with newlines", ["ab\n" x int($K60 / 3)],
      "single arg: \"ab\\n\" repeated 20480 times");
check("argc=1 60KB dots every 64", [("a" x 63 . ".") x int($K60 / 64)],
      "single arg: ('a'x63 . '.') repeated 960 times");
check("argc=1 60KB alternating case", [("aA" x int($K60 / 2))],
      "single arg: 'aA' repeated 30720 times");
check("argc=1 60KB high bytes cycle",
      [ join('', map { chr(0x80 + ($_ % 0x80)) } (0 .. $K60 - 1)) ],
      "single arg: 61440 bytes cycling 0x80..0xff");
check("argc=4 four 60KB args", [ ("a" x $K60) x 4 ],
      "four args each 61440 'a' bytes");
check("argc=10 ten 16KB args", [ ("z" x 16384) x 10 ],
      "ten args each 16384 'z' bytes");
check("argc=50 fifty 4KB args", [ ("y" x 4096) x 50 ],
      "fifty args each 4096 'y' bytes");

# 11. Every byte value 0x01..0xff as a lone one-byte argument (0x00 impossible).
for my $bv (1 .. 255) {
    check(sprintf("argc=1 single byte 0x%02x", $bv), [ chr($bv) ]);
}
for (my $bv = 1; $bv <= 255; $bv += 2) {
    check(sprintf("argc=2 byte 0x%02x + empty", $bv), [ chr($bv), "" ]);
    check(sprintf("argc=3 empty + byte 0x%02x + dot", $bv), [ "", chr($bv), "." ]);
}
# two-byte combos of interesting bytes as a single arg, arity 1 and 2
my @IB = (0x01, 0x09, 0x0a, 0x0d, 0x20, 0x2d, 0x2e, 0x41, 0x5a, 0x61,
          0x7a, 0x7f, 0x80, 0xc3, 0xed, 0xf0, 0xfe, 0xff);
for my $x (@IB) {
    for my $y (@IB) {
        check(sprintf("argc=1 bytes %02x%02x", $x, $y), [ chr($x) . chr($y) ]);
    }
}

print "-" x 72, "\n";
print "cases executed: $count\n";
print "mismatches: " . scalar(@mismatches) . "\n";
exit 0;

