sub run_bin {
    my ($bin, $argv, $out, $err, $argv0, $no_argv0) = @_;
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $out) or POSIX::_exit(126);
        open(STDERR, '>', $err) or POSIX::_exit(126);
        my @list;
        if ($no_argv0) { @list = @$argv }
        else { @list = ((defined $argv0 ? $argv0 : $bin), @$argv) }
        exec { $bin } @list;
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?;
    return ($st & 127) ? "sig" . ($st & 127) : "exit" . ($st >> 8);
}

